        return False

    term1 = m**2 + n
    term2 = m + n**2

    if term1 < 2 or term2 < 2:
        return False

    # Check if term1 is a power of p^A, A >= 2
    A = 0
    temp1 = term1
    if temp1 % p != 0:
        return False # Should not happen if term1 is p^A
    while temp1 > 1:
        temp1 //= p
        A += 1
    if A < 2:
