import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_power_of_p(N, p, min_exponent=2):
    if N <= 1:
        return False

    # Check if N is divisible by p
    if N % p != 0:
        return False

    # Count the exponent A such that N = p^A
    A = 0
    temp_N = N
    while temp_N > 1:
        if temp_N % p != 0:
            return False # Not a power of p
        temp_N //= p
        A += 1

    return A >= min_exponent

solutions = []
primes = [p for p in range(2, 31) if is_prime(p)]

# Search space expansion: p <= 30, m, n up to 30
MAX_MN = 30 

print(f"Starting search for primes p <= 30, m, n <= {MAX_MN}...")

for p in primes:
    for m in range(1, MAX_MN + 1):
        for n in range(1, MAX_MN + 1):
            # Check constraints

            # 1. m^2 + n must be p^A, A >= 2
            m2_plus_n = m**2 + n
            if not is_power_of_p(m2_plus_n, p, min_exponent=2):
                continue

            # 2. m + n^2 must be p^B, B >= 2
            m_plus_n2 = m + n**2
            if not is_power_of_p(m_plus_n2, p, min_exponent=2):
                continue

            # If both conditions are met, we found a solution
            solutions.append((m, n, p))

print("\n--- Solutions Found ---")
if solutions:
    for sol in solutions:
        m, n, p = sol
        m2n = m**2 + n
        m_n2 = m + n**2
